lifecycle.css:
/* Keep search, subscriptions, navigation, comments and the player intact. */
ytd-browse[page-subtype="home"] ytd-rich-grid-renderer { display: none !important; }
ytd-browse[page-subtype="home"]::before { content: "Choose what to watch: use Search or Subscriptions."; display: block; margin: 48px 24px; text-align: center; font: 16px/1.5 Roboto, Arial, sans-serif; color: var(--yt-spec-text-secondary); }
ytd-watch-flexy #related { display: none !important; }
ytd-rich-shelf-renderer[is-shorts], ytd-reel-shelf-renderer,
ytd-guide-entry-renderer:has(a[href^="/shorts"]), ytd-mini-guide-entry-renderer:has(a[href^="/shorts"]),
ytd-rich-item-renderer:has(a[href^="/shorts/"]), ytd-video-renderer:has(a[href^="/shorts/"]) { display: none !important; }
